import fitz, re, os
from collections import defaultdict

INPUTS = [f'/root/paper{i}.pdf' for i in range(1,4)]
OUT_DIR = '/root/redacted'
os.makedirs(OUT_DIR, exist_ok=True)

email_re = re.compile(r'[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}')
arxiv_re = re.compile(r'\barxiv\b|arxiv\.org|arxiv\s*:|arxiv:', re.I)
arxiv_id_re = re.compile(r'\b\d{4}\.\d{4,5}(v\d+)?\b')
correspondence_re = re.compile(r'correspondence|contact|respondence to', re.I)
ack_re = re.compile(r'^\s*acknowledg(e)?ments\b', re.I)
refs_re = re.compile(r'^\s*references\b|^\s*bibliography\b', re.I)

# affiliation keywords (case-insensitive)
affil_keywords = [
    'university','institute','department','school','college','laboratory','laboratories',
    'lab','centre','center','company','inc','llc','ltd','corporation','corp','gmbh',
    'carnegie','duke','adobe','renmin','cornell','georgia institute','duke kunshan',
    'multimodal art','carnegie mellon'
]

affil_re = re.compile(r'(' + '|'.join(re.escape(k) for k in affil_keywords) + r')', re.I)

# Detect author line heuristically

def is_author_line(text):
    t = text.strip()
    if len(t) < 3:
        return False
    # Many commas or semicolons
    if t.count(',') + t.count(';') >= 2:
        return True
    # Superscripts/markers with names
    if any(ch in t for ch in ['*','†','‡','∗','♠','♣','^']):
        # ensure it looks like names
        if re.search(r'[A-Z][a-z]+\s+[A-Z][a-z]+', t):
            return True
    # numbers for affiliations
    if re.search(r'\b[1-9]\b', t) and re.search(r'[A-Z][a-z]+\s+[A-Z][a-z]+', t):
        return True
    return False


def line_bbox(line):
    # union of spans bbox
    x0=y0=1e9; x1=y1=-1e9
    for sp in line.get('spans', []):
        bx0,by0,bx1,by1 = sp['bbox']
        x0=min(x0,bx0); y0=min(y0,by0); x1=max(x1,bx1); y1=max(y1,by1)
    if x1 < x0 or y1 < y0:
        return None
    return fitz.Rect(x0,y0,x1,y1)

summary = defaultdict(int)

for in_path in INPUTS:
    doc = fitz.open(in_path)
    # remove metadata
    doc.set_metadata({
        'title':'', 'author':'', 'subject':'', 'keywords':'', 'creator':'', 'producer':'', 'creationDate':'', 'modDate':''
    })
    try:
        doc.set_xml_metadata('')
    except Exception:
        pass

    ack_mode = False

    for pno in range(doc.page_count):
        page = doc[pno]
        height = page.rect.height
        text_dict = page.get_text('dict')
        # find abstract line y0
        abstract_y = None
        for block in text_dict.get('blocks', []):
            for line in block.get('lines', []):
                line_text = ''.join(sp['text'] for sp in line.get('spans', [])).strip()
                if re.match(r'^\s*abstract\b', line_text, re.I):
                    bbox = line_bbox(line)
                    if bbox:
                        abstract_y = bbox.y0
                        break
            if abstract_y is not None:
                break
        # iterate lines
        for block in text_dict.get('blocks', []):
            for line in block.get('lines', []):
                line_text = ''.join(sp['text'] for sp in line.get('spans', [])).strip()
                if not line_text:
                    continue
                bbox = line_bbox(line)
                if not bbox:
                    continue
                y0 = bbox.y0

                # References heading ends acknowledgements
                if refs_re.match(line_text):
                    ack_mode = False

                # Acknowledgements start
                if ack_re.match(line_text):
                    ack_mode = True

                redact = False

                # If inside acknowledgements, redact line
                if ack_mode:
                    redact = True

                # Email lines
                if email_re.search(line_text):
                    redact = True

                # arXiv lines and IDs
                if arxiv_re.search(line_text) or arxiv_id_re.search(line_text):
                    redact = True

                # Correspondence line
                if correspondence_re.search(line_text):
                    redact = True

                # First page author/affiliation/venue lines above abstract
                if pno == 0:
                    upper_bound = abstract_y if abstract_y is not None else height * 0.45
                    if y0 < upper_bound:
                        if is_author_line(line_text):
                            redact = True
                        if affil_re.search(line_text):
                            redact = True
                        # Possible venue acceptance lines on title block
                        if re.search(r'\baccepted\b|\bto appear\b|\bproceedings\b|\bconference\b|\bworkshop\b|\bjournal\b', line_text, re.I):
                            redact = True

                if redact:
                    page.add_redact_annot(bbox, fill=(1,1,1))
                    summary[in_path] += 1

        # Apply redactions for this page
        if page.first_annot:
            page.apply_redactions(images=fitz.PDF_REDACT_IMAGE_NONE)

    out_path = os.path.join(OUT_DIR, os.path.basename(in_path))
    doc.save(out_path, garbage=4, deflate=True)
    doc.close()

print('Redaction summary (lines redacted):')
for k,v in summary.items():
    print(os.path.basename(k), v)
